cat > mock_dap.py <<'PY'
import json, sys
seq = 1
def send(obj):
    global seq
    obj['seq'] = seq
    seq += 1
    body = json.dumps(obj).encode('utf-8')
    sys.stdout.buffer.write(f'Content-Length: {len(body)}\r\n\r\n'.encode('ascii') + body)
    sys.stdout.buffer.flush()
def read_msg():
    hdrs = {}
    while True:
        line = sys.stdin.buffer.readline()
        if not line:
            return None
        if line in (b'\r\n', b'\n'):
            break
        k, _, v = line.decode('ascii').partition(':')
        hdrs[k.strip().lower()] = v.strip()
    n = int(hdrs.get('content-length', '0'))
    return json.loads(sys.stdin.buffer.read(n).decode('utf-8'))
while True:
    msg = read_msg()
    if msg is None:
        break
    cmd = msg.get('command')
    rseq = msg.get('seq')
    if cmd == 'initialize':
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{'supportsConfigurationDoneRequest':True,'supportsEvaluateForHovers':True}})
        send({'type':'event','event':'initialized'})
    elif cmd == 'launch':
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd})
    elif cmd == 'configurationDone':
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd})
        send({'type':'event','event':'stopped','body':{'reason':'entry','threadId':1,'allThreadsStopped':True}})
    elif cmd == 'threads':
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{'threads':[{'id':1,'name':'main'}]}})
    elif cmd == 'stackTrace':
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{'stackFrames':[{'id':10,'name':'main','line':5,'column':1,'source':{'name':'app.py','path':'app.py'}}],'totalFrames':1}})
    elif cmd == 'setBreakpoints':
        bps = msg.get('arguments',{}).get('breakpoints',[])
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{'breakpoints':[{'id':1,'verified':True,'line':b.get('line',1)} for b in bps]}})
    elif cmd == 'scopes':
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{'scopes':[{'name':'Locals','variablesReference':100,'expensive':False}]}})
    elif cmd == 'variables':
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{'variables':[{'name':'answer','value':'42','type':'int','variablesReference':0}]}})
    elif cmd == 'evaluate':
        expr = msg.get('arguments',{}).get('expression','')
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{'result':'42' if expr=='answer' else expr,'type':'int','variablesReference':0}})
    elif cmd in ('disconnect', 'terminate'):
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd})
        break
    else:
        send({'type':'response','request_seq':rseq,'success':True,'command':cmd,'body':{}})
PY
